INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.969338', 1, 3, 2, 1, NULL, '#워케이션추천', '최고의 워케이션 경험!', '업무 환경이 잘 갖춰져 있고 주변 경관도 아름다워 집중이 잘 됐습니다. 체크인부터 체크아웃까지 불편함 없이 이용했습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:30.970878', 2, 4, 3, 1, NULL, '#재방문확정', '업무와 휴식을 동시에', '객실 책상이 넓고 콘센트 위치가 좋아서 노트북 작업하기 편했습니다. 저녁에는 주변 산책로도 만족스러웠습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:30.971392', 3, 5, 4, 1, NULL, '#힐링', '재방문 의사 있어요', '회의 준비 때문에 방문했는데 Wi-Fi가 안정적이고 조용해서 좋았습니다. 직원 응대도 빠른 편이었습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.971905', 4, 6, 5, 1, NULL, '#업무효율UP', '시설이 너무 좋아요', '가족 일정과 업무를 같이 처리하기에 적당했습니다. 침구와 욕실 상태가 깔끔해서 재방문 의사가 있습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:30.97242', 5, 7, 6, 1, NULL, '#가족여행', '직원 서비스 최고', '사진보다 실제 공간이 더 넓게 느껴졌고, 공용 라운지 분위기가 편안했습니다. 주차도 어렵지 않았습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:30.972938', 6, 8, 7, 1, NULL, '#혼자여행', '위치가 완벽합니다', '출장 전후로 하루 더 머물렀는데 휴식과 업무 균형이 좋았습니다. 위치 접근성도 기대 이상이었습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.972938', 7, 9, 8, 1, NULL, '#팀워크', '넓고 쾌적한 공간', '장기 체류용으로 필요한 편의시설이 대부분 갖춰져 있었습니다. 다만 성수기에는 조금 붐빌 것 같습니다.');
