INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:30.978496', 71, 147, 146, 1, NULL, '#비즈니스출장', '장기 체류에도 편했습니다', '장기 체류용으로 필요한 편의시설이 대부분 갖춰져 있었습니다. 다만 성수기에는 조금 붐빌 것 같습니다.');
