INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.979496', 73, 149, 148, 1, NULL, '#워케이션추천', '최고의 워케이션 경험!', '업무 환경이 잘 갖춰져 있고 주변 경관도 아름다워 집중이 잘 됐습니다. 체크인부터 체크아웃까지 불편함 없이 이용했습니다.');
