INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:30.982497', 108, 253, 252, 1, NULL, '#장기숙박', '다음 팀 워크숍도 여기로', '가족 일정과 업무를 같이 처리하기에 적당했습니다. 침구와 욕실 상태가 깔끔해서 재방문 의사가 있습니다.');
