INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.986497', 145, 360, 359, 2, NULL, '#워케이션추천', '최고의 워케이션 경험!', '업무 환경이 잘 갖춰져 있고 주변 경관도 아름다워 집중이 잘 됐습니다. 체크인부터 체크아웃까지 불편함 없이 이용했습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:30.986497', 146, 361, 360, 2, NULL, '#재방문확정', '업무와 휴식을 동시에', '객실 책상이 넓고 콘센트 위치가 좋아서 노트북 작업하기 편했습니다. 저녁에는 주변 산책로도 만족스러웠습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:30.986497', 147, 362, 361, 2, NULL, '#힐링', '재방문 의사 있어요', '회의 준비 때문에 방문했는데 Wi-Fi가 안정적이고 조용해서 좋았습니다. 직원 응대도 빠른 편이었습니다.');
