INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:30.992496', 219, 571, 570, 2, NULL, '#힐링', '재방문 의사 있어요', '회의 준비 때문에 방문했는데 Wi-Fi가 안정적이고 조용해서 좋았습니다. 직원 응대도 빠른 편이었습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:30.992496', 220, 572, 571, 2, NULL, '#업무효율UP', '시설이 너무 좋아요', '가족 일정과 업무를 같이 처리하기에 적당했습니다. 침구와 욕실 상태가 깔끔해서 재방문 의사가 있습니다.');
