INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:30.997496', 293, 722, 721, 3, NULL, '#가족여행', '직원 서비스 최고', '사진보다 실제 공간이 더 넓게 느껴졌고, 공용 라운지 분위기가 편안했습니다. 주차도 어렵지 않았습니다.');
