INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:31.008496', 441, 146, 1145, 4, NULL, '#오션뷰', '조용해서 집중하기 좋았어요', '업무 환경이 잘 갖춰져 있고 주변 경관도 아름다워 집중이 잘 됐습니다. 체크인부터 체크아웃까지 불편함 없이 이용했습니다.');
