INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:31.070496', 1178, 140, 3139, 11, NULL, '#재방문확정', '업무와 휴식을 동시에', '객실 책상이 넓고 콘센트 위치가 좋아서 노트북 작업하기 편했습니다. 저녁에는 주변 산책로도 만족스러웠습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 5, '2026-06-11 14:33:31.070496', 1179, 141, 3140, 11, NULL, '#힐링', '재방문 의사 있어요', '회의 준비 때문에 방문했는데 Wi-Fi가 안정적이고 조용해서 좋았습니다. 직원 응대도 빠른 편이었습니다.');
INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 3, '2026-06-11 14:33:31.070496', 1180, 142, 3141, 11, NULL, '#업무효율UP', '시설이 너무 좋아요', '가족 일정과 업무를 같이 처리하기에 적당했습니다. 침구와 욕실 상태가 깔끔해서 재방문 의사가 있습니다.');
