INSERT INTO public.review (del_yn, hide_yn, rating, created_at, id, member_id, reservation_id, space_id, updated_at, tag, title, content) VALUES ('N', 'N', 4, '2026-06-11 14:33:31.072496', 1214, 182, 3181, 11, NULL, '#재방문확정', '업무와 휴식을 동시에', '출장 전후로 하루 더 머물렀는데 휴식과 업무 균형이 좋았습니다. 위치 접근성도 기대 이상이었습니다.');
