INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.302601', 1, 1, NULL, '예약은 어떻게 하나요?', '홈페이지에서 원하는 공간을 선택하고, 날짜와 인원수를 입력한 후 결제를 완료하시면 예약이 확정됩니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3036', 2, 1, NULL, '취소 및 환불 정책은 어떻게 되나요?', '체크인 7일 전까지 취소 시 전액 환불, 3~7일 전 50% 환불, 3일 이내 취소 시 환불 불가입니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3036', 3, 1, NULL, '워케이션과 일반 숙박의 차이는 무엇인가요?', '워케이션 객실은 업무용 책상, 고속 Wi-Fi, 호텔 내 공유 오피스 공간이 무료로 포함됩니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 4, 1, NULL, '회원가입은 어떻게 하나요?', '상단 메뉴의 [회원가입] 버튼을 클릭하여 이름, 이메일, 비밀번호를 입력하면 가입이 완료됩니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 5, 1, NULL, '쿠폰은 어디서 사용하나요?', '예약 결제 단계에서 보유 쿠폰을 선택하시면 할인이 적용됩니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 6, 1, NULL, '셀러(공간 제공자)로 등록하려면 어떻게 해야 하나요?', '마이페이지 > 셀러 신청 메뉴에서 사업자 정보와 계좌 정보를 입력하고 신청하시면 검토 후 셀러 권한이 부여됩니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 7, 1, NULL, '결제 수단은 무엇을 지원하나요?', '신용카드, 체크카드, 카카오페이, 네이버페이, 토스페이 등 다양한 결제 수단을 지원합니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 8, 1, NULL, '체크인/체크아웃 시간은 어떻게 되나요?', '기본 체크인 시간은 오후 3시, 체크아웃 시간은 오전 11시입니다. 공간마다 상이할 수 있으니 상세 페이지를 확인해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 9, 1, NULL, '예약 확인은 어떻게 하나요?', '마이페이지 > 예약 내역 메뉴에서 모든 예약 현황을 확인하실 수 있습니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 10, 1, NULL, '리뷰는 언제 작성할 수 있나요?', '이용 완료(체크아웃) 후 마이페이지 > 예약 내역에서 리뷰 작성이 가능합니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 11, 1, NULL, '분실물 신고는 어떻게 하나요?', '고객센터(1588-0000)로 연락주시거나, 이용하신 공간에 직접 문의해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 12, 1, NULL, '유아/어린이 동반이 가능한가요?', '공간마다 정책이 다릅니다. 공간 상세 페이지의 이용 조건을 확인해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 13, 1, NULL, '반려동물 동반이 가능한가요?', '반려동물 동반은 원칙적으로 불가능합니다. 단, 펫 프렌들리 공간으로 등록된 숙소는 가능합니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 14, 1, NULL, 'Wi-Fi는 무료로 제공되나요?', '모든 워케이션 공간에서 고속 무료 Wi-Fi를 제공합니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 15, 1, NULL, '주차 공간은 있나요?', '대부분의 공간에서 무료 주차를 지원합니다. 공간 상세 페이지에서 주차 여부를 확인해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 16, 1, NULL, '조식 서비스는 제공되나요?', '공간에 따라 조식 포함 여부가 다릅니다. 예약 전 상세 페이지에서 확인해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 17, 1, NULL, '비즈니스 영수증(세금계산서) 발급이 가능한가요?', '법인 카드 결제 시 세금계산서 발급이 가능합니다. 고객센터로 문의해 주세요.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 18, 1, NULL, '예약 후 날짜 변경이 가능한가요?', '체크인 7일 전까지는 마이페이지에서 날짜 변경이 가능합니다. 그 이후에는 취소 후 재예약을 해야 합니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 19, 1, NULL, '공간 등록 심사는 얼마나 걸리나요?', '공간 등록 신청 후 영업일 기준 3~5일 내 심사 결과를 안내드립니다.');
INSERT INTO public.faq (del_yn, created_at, id, member_id, updated_at, question, answer) VALUES ('N', '2026-06-11 14:33:31.3046', 20, 1, NULL, '결제 오류가 발생했어요. 어떻게 해야 하나요?', '결제 화면에서 오류 발생 시 카드사 또는 고객센터(1588-0000)로 문의해 주세요. 이중 결제 여부도 확인해 드립니다.');
