INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'Y', '2026-06-11 14:33:31.324601', 1, 1, NULL, 'Workation 서비스 오픈 안내', '워케이션 통합 예약 플랫폼 정식 서비스를 시작합니다. 코워킹 스페이스와 숙박을 한 번에 예약하세요!');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'Y', '2026-06-11 14:33:31.325601', 2, 1, NULL, '신규 가입 혜택 안내 (웰컴 쿠폰 10% 할인)', '신규 회원 가입 시 자동으로 10% 할인 웰컴 쿠폰이 지급됩니다. 유효기간 7일이니 빠르게 사용하세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.325601', 3, 1, NULL, '[점검] 2026년 6월 7일(일) 새벽 2시~4시 서비스 점검', '서비스 안정화 작업으로 인해 해당 시간 동안 예약 서비스가 일시 중단됩니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 4, 1, NULL, '결제 시스템 개선 — 네이버페이·토스페이 추가', '더욱 빠르고 안전한 결제를 위해 결제 시스템을 개선하였습니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 5, 1, NULL, '셀러(공간 제공자) 모집 안내', '워케이션 공간을 보유하고 계신 사업자를 모집합니다. 셀러 신청 후 심사를 통해 공간을 등록해 보세요!');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 6, 1, NULL, '여름 시즌 특별 프로모션 — 강원도 15% 할인', '7월~8월 여름 시즌을 맞아 강원도 워케이션 패키지 15% 할인 프로모션을 진행합니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 7, 1, NULL, '리뷰 이벤트 — 베스트 리뷰 선정', '이달의 베스트 리뷰 작성자를 선정합니다. 상위 10명에게 5만원 할인 쿠폰을 드립니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 8, 1, NULL, '모바일 앱 출시 예정 (2026년 8월)', '워케이션 모바일 앱이 2026년 8월 출시 예정입니다. 앱 스토어에서 사전 알림을 신청해 주세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 9, 1, NULL, '개인정보 처리방침 개정 안내 (2026.06.01)', '개인정보 처리방침이 개정되었습니다. 변경 내용을 확인해 주시기 바랍니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 10, 1, NULL, '워케이션 추천 지역 — 강원도 속초', '강원도 속초는 바다와 산이 공존하는 워케이션 최적지입니다. 이번 주 특가 상품을 확인해 보세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 11, 1, NULL, '법인 단체 예약 서비스 오픈', '법인 고객을 위한 단체 예약 서비스가 오픈되었습니다. 5인 이상 단체 예약 시 추가 혜택을 드립니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 12, 1, NULL, '공간 환경 사진 업데이트 안내', '등록된 공간의 최신 사진으로 업데이트되었습니다. 더욱 생생한 공간 정보를 확인해 보세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 13, 1, NULL, '취소/환불 정책 개정 안내', '2026년 6월 1일부터 취소 및 환불 정책이 일부 변경됩니다. 예약 전 반드시 확인해 주세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 14, 1, NULL, '워케이션 트렌드 리포트 2026 발표', '2026 워케이션 트렌드 리포트를 공개합니다. 올해 가장 인기 있는 워케이션 지역과 스타일을 확인해 보세요.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 15, 1, NULL, '제주도 워케이션 특가 상품 출시', '제주도 워케이션 특가 패키지가 출시되었습니다. 7월 말 이전 예약 시 20% 추가 할인 혜택이 제공됩니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 16, 1, NULL, '생일 쿠폰 서비스 시작', '회원 생일에 특별한 20% 할인 생일 쿠폰을 드립니다. 생년월일을 등록하고 혜택을 받아보세요!');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.326601', 17, 1, NULL, '고객센터 운영 시간 변경 안내', '고객센터 운영 시간이 평일 오전 9시~오후 6시로 변경됩니다. (기존: 오전 10시~오후 5시)');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.3276', 18, 1, NULL, '워케이션 후기 공모전 개최', '나의 워케이션 경험을 공유해주세요. 채택된 후기에는 최대 10만원 상품권을 드립니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.3276', 19, 1, NULL, '새로운 파트너 공간 추가 — 경기권 확대', '경기도 수원, 광교, 판교 지역 워케이션 공간이 새롭게 추가되었습니다.');
INSERT INTO public.notice (del_yn, pin_yn, created_at, id, member_id, updated_at, title, content) VALUES ('N', 'N', '2026-06-11 14:33:31.3276', 20, 1, NULL, '워케이션 정기 이용권 출시 예정', '월 단위로 워케이션 공간을 이용할 수 있는 정기 이용권 서비스가 2026년 하반기 출시 예정입니다.');
